function useStoredCart() {
  const [cart, setCart] = useState<CartItem[]>(() => {
    try { return JSON.parse(localStorage.getItem('sweet-delight-cart') || '[]'); } catch { return []; }
  });
  useEffect(() => localStorage.setItem('sweet-delight-cart', JSON.stringify(cart)), [cart]);
  const add = (product: Product, size = 'Standard', note = '') => {
    setCart(items => {
      const found = items.find(item => item.id === product.id && item.size === size);
      return found ? items.map(item => item === found ? { ...item, quantity: item.quantity + 1 } : item) : [...items, { ...product, quantity: 1, size, note }];
    });
    toast.success('Added to your pastry box', { description: product.name });
  };
  const change = (id: string, size: string, amount: number) => setCart(items => items.map(item => item.id === id && item.size === size ? { ...item, quantity: Math.max(0, item.quantity + amount) } : item).filter(item => item.quantity > 0));
  const remove = (id: string, size: string) => setCart(items => items.filter(item => !(item.id === id && item.size === size)));
  return { cart, add, change, remove, clear: () => setCart([]) };
}

function Header({ count }: { count: number }) {
  const [open, setOpen] = useState(false);
  const [location] = useLocation();
  return <header className="sticky top-0 z-40 border-b border-[hsl(var(--brand-ink)/.12)] bg-[hsl(var(--brand-pink))] shadow-[0_2px_18px_hsl(var(--brand-ink)/.08)]">
    <div className="section-wrap flex h-[76px] items-center justify-between">
      <Link href="/" className="group flex h-full items-center overflow-hidden" data-testid="link-logo">
        <img src="/sweet-delight-header-logo.png" alt="Frost Craft — Delight in every bite" className="block h-auto max-h-[62px] w-[164px] object-contain transition-transform duration-300 group-hover:scale-[1.02] sm:w-[184px]" />
      </Link>
      <nav className="hidden items-center gap-8 text-sm font-medium md:flex" aria-label="Main navigation">
        {[['Home', '/'], ['Menu', '/menu'], ['Our story', '/about'], ['Contact', '/contact']].map(([item, href]) => <Link key={item} href={href} className={cn('link-underline text-[hsl(var(--brand-ink)/.75)] transition-colors hover:text-[hsl(var(--brand-ink))]', location === href && 'text-[hsl(var(--brand-ink))]')} data-testid={`link-nav-${item.toLowerCase().replace(' ', '-')}`}>{item}</Link>)}
      </nav>
      <div className="flex items-center gap-2">
        <Link href="/menu" className="hidden rounded-full p-3 text-[hsl(var(--brand-ink)/.7)] transition-colors hover:bg-[hsl(var(--brand-ink)/.08)] hover:text-[hsl(var(--brand-ink))] sm:block" data-testid="link-search"><Search size={19}/></Link>
        <Link href="/cart" className="relative rounded-full p-3 text-[hsl(var(--brand-ink)/.7)] transition-colors hover:bg-[hsl(var(--brand-ink)/.08)] hover:text-[hsl(var(--brand-ink))]" data-testid="link-cart"><ShoppingBag size={19}/>{count > 0 && <span className="absolute right-0 top-0 flex h-5 min-w-5 items-center justify-center rounded-full bg-[hsl(var(--brand-ink))] px-1 text-[10px] font-bold text-[hsl(var(--brand-pink))]">{count}</span>}</Link>
        <button className="rounded-full p-3 text-[hsl(var(--brand-ink))] md:hidden" onClick={() => setOpen(!open)} aria-label="Toggle menu" data-testid="button-mobile-menu">{open ? <X size={20}/> : <MenuIcon size={20}/>}</button>
      </div>
    </div>
    {open && <nav className="border-t border-[hsl(var(--brand-ink)/.12)] bg-[hsl(var(--brand-pink))] px-5 py-5 md:hidden" aria-label="Mobile navigation">
      <div className="section-wrap flex flex-col gap-5 text-lg font-display text-[hsl(var(--brand-ink))]">
        <Link href="/" onClick={() => setOpen(false)} data-testid="link-mobile-home">Home</Link><Link href="/menu" onClick={() => setOpen(false)} data-testid="link-mobile-menu">The menu</Link><Link href="/about" onClick={() => setOpen(false)} data-testid="link-mobile-about">Our story</Link><Link href="/contact" onClick={() => setOpen(false)} data-testid="link-mobile-contact">Come say hello</Link>
      </div>
    </nav>}
  </header>;
}

